127	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
128	    @Override
129	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
130	        validateRequiredFields(ownerFieldsDto);
131	        HttpHeaders headers = new HttpHeaders();
132	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
133	        String address = normalizeAddress(ownerFieldsDto.getAddress());
134	        owner.setAddress(address);
135	        rejectCityAtCapacity(owner.getCity());
136	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
137	            assignHousehold(owner, ownerFieldsDto.getLastName(), address);
138	        } else {
139	            rejectDuplicateHousehold(ownerFieldsDto.getLastName(), address);
140	        }
141	        String telephone = normalizeTelephone(ownerFieldsDto.getTelephone());
142	        rejectDuplicateTelephone(telephone);
143	        owner.setTelephone(telephone);
144	        owner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
145	        if (owner.getRegistrationDate() == null) {
146	            owner.setRegistrationDate(LocalDate.now());
147	        }
148	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
149	        owner.setCustomerCode(generateCustomerCode(owner.getCity(), owner.getLastName()));
150	        this.clinicService.saveOwner(owner);
151	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
152	        headers.setLocation(UriComponentsBuilder.newInstance()
153	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
154	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
155	    }
